"""Embedded interface for the local Parison Workbench."""

RECONCILIATION_SCRIPT = r"""
const reconciliationForm=document.getElementById('reconciliation-form'),reconciliationEntries=document.getElementById('reconciliation-entries'),reconciliationStatus=document.getElementById('reconciliation-status'),reconciliationReview=document.getElementById('reconciliation-review'),reconciliationReviewRows=document.getElementById('reconciliation-review-rows'),reconciliationRunStatus=document.getElementById('reconciliation-run-status'),reconciliationStart=document.getElementById('reconciliation-start'),reconciliationCancel=document.getElementById('reconciliation-cancel'),reconciliationResult=document.getElementById('reconciliation-result'),reconciliationResultRows=document.getElementById('reconciliation-result-rows'),reconciliationDiagnosis=document.getElementById('reconciliation-diagnosis'),reconciliationDiagnosisRows=document.getElementById('reconciliation-diagnosis-rows');
function renderReconciliationDiagnosis(diagnosis,target){const counts=diagnosis.reason_counts;target.replaceChildren();rows({'Overall outcome':diagnosis.outcome,'Alignment outcome':diagnosis.alignment_outcome,'Alignment reasons':diagnosis.alignment_reason_codes,'Dataset parity · PASS':diagnosis.dataset_outcome_counts.PASS,'Dataset parity · FAIL':diagnosis.dataset_outcome_counts.FAIL,'Dataset parity · INCONCLUSIVE':diagnosis.dataset_outcome_counts.INCONCLUSIVE,'Identity · duplicate keys':counts.identity_duplicate_keys,'Identity · null key rows':counts.identity_null_key_rows,'Reference · orphan rows':counts.reference_orphan_rows,'Reference · ambiguous parent rows':counts.reference_ambiguous_parent_rows,'Reference · null failure rows':counts.reference_null_failure_rows,'Conservation · different groups':counts.conservation_different_groups,'Conservation · child only groups':counts.conservation_child_only_groups,'Conservation · duplicate parent groups':counts.conservation_duplicate_parent_groups,'Conservation · null measure rows':counts.conservation_null_measure_rows,'Conservation · parents without children':counts.conservation_parent_without_children_groups},'',target)}
let reconciliationRevision=0,reconciliationReviewed=null,reconciliationOutput=null,reconciliationBusy=false;
function clearReconciliation(){reconciliationRevision++;reconciliationReviewed=null;reconciliationReview.hidden=true;reconciliationResult.hidden=true;reconciliationDiagnosis.hidden=true;reconciliationOutput=null;reconciliationStatus.textContent='Inputs changed. Review exact local bytes again.'}
function addReconciliationDataset(){const item=document.getElementById('reconciliation-entry-template').content.firstElementChild.cloneNode(true);item.querySelector('.reconciliation-remove').addEventListener('click',()=>{item.remove();clearReconciliation()});reconciliationEntries.append(item);clearReconciliation()}
document.getElementById('reconciliation-add').addEventListener('click',addReconciliationDataset);addReconciliationDataset();
reconciliationForm.addEventListener('input',clearReconciliation);
function reconciliationRequest(){const value=name=>reconciliationForm.elements.namedItem(name).value;return {alignment:value('alignment'),reconciliation:value('reconciliation'),receipt:value('receipt'),output:value('output'),datasets:[...reconciliationEntries.children].map(item=>Object.fromEntries(['id','recipe','baseline','candidate'].map(name=>[name,item.querySelector('[data-field="'+name+'"]').value])))}}
reconciliationForm.addEventListener('submit',async event=>{event.preventDefault();clearReconciliation();const revision=reconciliationRevision,request=reconciliationRequest();reconciliationStatus.textContent='Checking declared policies, receipt and source identities...';try{const response=await post('/api/reconciliation-review',request);if(!response.ok)throw Error();const reviewed=await response.json();if(revision!==reconciliationRevision)return;reconciliationReviewRows.replaceChildren();rows(reviewed,'',reconciliationReviewRows);reconciliationReviewed={...request,review_id:reviewed.review_id};reconciliationReview.hidden=false;reconciliationStart.disabled=false;reconciliationStatus.textContent=reviewed.dataset_count+' dataset(s) reviewed. Examine the identities before running.'}catch(error){if(revision===reconciliationRevision)reconciliationStatus.textContent='Review rejected. Check declarations, receipt, every dataset policy and local paths.'}});
reconciliationStart.addEventListener('click',async()=>{if(!reconciliationReviewed||reconciliationBusy)return;const request=reconciliationReviewed,revision=reconciliationRevision;reconciliationBusy=true;reconciliationStart.disabled=true;reconciliationCancel.disabled=false;reconciliationRunStatus.textContent='Rechecking reviewed bytes before local execution...';const progress=setInterval(async()=>{try{const response=await post('/api/reconciliation-run-status',{});if(response.ok){const state=await response.json();if(revision===reconciliationRevision)reconciliationRunStatus.textContent='Reconciliation: '+state.phase+'...'}}catch(error){}},500);try{const response=await post('/api/reconciliation-run',request);if(!response.ok)throw Error();const executed=await response.json();if(revision!==reconciliationRevision)return;reconciliationResultRows.replaceChildren();rows(executed.evidence,'',reconciliationResultRows);reconciliationResult.hidden=false;reconciliationOutput=request.output;reconciliationRunStatus.textContent=executed.catalog_status==='failed'?'Bundle published and verified, but History registration failed. Open the output in Results.':'Bundle published, verified and registered in History.'}catch(error){if(revision===reconciliationRevision)reconciliationRunStatus.textContent='Run stopped or rejected. Check Results for a published bundle before reusing the output path.'}finally{clearInterval(progress);reconciliationBusy=false;reconciliationCancel.disabled=true}});
reconciliationCancel.addEventListener('click',async()=>{reconciliationCancel.disabled=true;reconciliationRunStatus.textContent='Cancellation requested. Waiting for a safe checkpoint...';try{const response=await post('/api/cancel-reconciliation',{});if(!response.ok)reconciliationRunStatus.textContent='Run completed before cancellation could be applied.'}catch(error){reconciliationRunStatus.textContent='Cancellation request failed; check Results for the output.'}});
document.getElementById('reconciliation-diagnose').addEventListener('click',async()=>{if(!reconciliationOutput)return;const output=reconciliationOutput,revision=reconciliationRevision;reconciliationRunStatus.textContent='Verifying preserved evidence for fixed reason counts...';try{const response=await post('/api/reconciliation-diagnosis',{bundle:output});if(!response.ok)throw Error();const diagnosis=await response.json();if(revision!==reconciliationRevision)return;renderReconciliationDiagnosis(diagnosis,reconciliationDiagnosisRows);reconciliationDiagnosis.hidden=false;reconciliationRunStatus.textContent='Diagnosis loaded from verified bundle; source files were not read.'}catch(error){if(revision===reconciliationRevision)reconciliationRunStatus.textContent='Diagnosis rejected. Reopen and verify the bundle in Results.'}});
"""

SUITE_SERIES_SCRIPT = r"""
const seriesForm=document.getElementById('series-form'),seriesBundles=document.getElementById('series-bundles'),seriesStatus=document.getElementById('series-status'),seriesResult=document.getElementById('series-result'),seriesCase=document.getElementById('series-case'),seriesGroup=document.getElementById('series-group'),seriesRows=document.getElementById('series-rows'),seriesExport=document.getElementById('series-export');
let seriesRevision=0,seriesReviewed=null;
function clearSeries(){seriesRevision++;seriesReviewed=null;seriesResult.hidden=true;seriesExport.disabled=true;seriesRows.replaceChildren();seriesCase.replaceChildren();seriesGroup.replaceChildren()}
seriesBundles.addEventListener('input',()=>{clearSeries();seriesStatus.textContent='Bundle order changed. Analyze again.'});
function renderSeriesGroup(){if(!seriesReviewed)return;const item=seriesReviewed.series.cases[Number(seriesCase.value)],group=item.groups[Number(seriesGroup.value)];seriesRows.replaceChildren();rows({case_ref:item.case_ref,policy_sha256:item.policy_sha256,comparison_mode:item.comparison_mode,runs:item.runs,input_transitions:item.input_transitions,group},'',seriesRows)}
function renderSeriesCase(){if(!seriesReviewed)return;const item=seriesReviewed.series.cases[Number(seriesCase.value)];seriesGroup.replaceChildren();item.groups.forEach((group,index)=>seriesGroup.add(new Option(group.kind+' / '+group.classification+' · '+group.group_id.slice(0,12),String(index))));renderSeriesGroup()}
seriesCase.addEventListener('change',renderSeriesCase);seriesGroup.addEventListener('change',renderSeriesGroup);
seriesForm.addEventListener('submit',async event=>{event.preventDefault();clearSeries();const revision=seriesRevision,bundles=seriesBundles.value.split('\n').map(value=>value.trim()).filter(Boolean);seriesStatus.textContent='Verifying each suite and its selected children...';try{const response=await post('/api/suite-series',{bundles});if(!response.ok)throw Error();const reviewed=await response.json();if(revision!==seriesRevision)return;seriesReviewed={...reviewed,bundles};reviewed.series.cases.forEach((item,index)=>seriesCase.add(new Option('Case '+(index+1)+' · '+item.comparison_mode+' · '+item.case_ref.slice(0,12),String(index))));renderSeriesCase();seriesResult.hidden=false;seriesExport.disabled=false;seriesStatus.textContent=reviewed.series.runs.length+' rehearsals in supplied order; '+reviewed.series.cases.length+' cases. Select a case and group to inspect every count. Order is not inferred chronology.'}catch(error){if(revision===seriesRevision)seriesStatus.textContent='Series rejected. Choose 2-16 distinct complete suites with matching policy, selection and case order.'}});
seriesExport.addEventListener('click',async()=>{if(!seriesReviewed)return;const revision=seriesRevision,request={bundles:seriesReviewed.bundles,review_id:seriesReviewed.review_id,output:document.getElementById('series-output').value};seriesExport.disabled=true;seriesStatus.textContent='Reverifying the reviewed series before atomic export...';try{const response=await post('/api/suite-series-export',request);if(!response.ok)throw Error();if(revision===seriesRevision)seriesStatus.textContent='Verified summary series exported to '+request.output+'. This does not establish cause, improvement or cutover readiness.'}catch(error){if(revision===seriesRevision)seriesStatus.textContent='Export rejected. Reanalyze changed bundles and choose a new output folder.'}finally{if(revision===seriesRevision)seriesExport.disabled=!seriesReviewed}});
"""

POLICY_REVIEW_SCRIPT = r"""
const policyForm=document.getElementById('policy-review-form'),policyStatus=document.getElementById('policy-review-status'),policySummary=document.getElementById('policy-review-summary'),policyRows=document.getElementById('policy-review-rows'),policyDetailsButton=document.getElementById('policy-details-button'),policyDetails=document.getElementById('policy-details'),policyHide=document.getElementById('policy-hide-details');
let policyRevision=0,policyReviewed=null;
function clearPolicyReview(){policyRevision++;policyReviewed=null;policySummary.hidden=true;policyRows.replaceChildren();policyDetailsButton.disabled=true;policyDetails.textContent='';policyDetails.hidden=true;policyHide.hidden=true}
policyForm.addEventListener('input',()=>{clearPolicyReview();policyStatus.textContent='Inputs changed. Review the summary again.'});
policyHide.addEventListener('click',()=>{policyRevision++;policyDetails.textContent='';policyDetails.hidden=true;policyHide.hidden=true;policyDetailsButton.disabled=!policyReviewed});
policyForm.addEventListener('submit',async event=>{
  event.preventDefault();clearPolicyReview();const revision=policyRevision;
  const request={baseline_recipe:document.getElementById('policy-baseline').value,candidate_recipe:document.getElementById('policy-candidate').value,evolution:document.getElementById('policy-evolution').value};
  policyStatus.textContent='Assessing the two policies under the explicit declaration...';
  try{const response=await post('/api/policy-review',request);if(!response.ok)throw Error();const reviewed=await response.json();if(revision!==policyRevision)return;
    rows(reviewed.summary,'',policyRows);policyReviewed={...request,review_id:reviewed.review_id};policySummary.hidden=false;policyDetailsButton.disabled=false;
    policyStatus.textContent=reviewed.summary.compatibility+' is a mechanical assessment, not policy approval. Unequal-policy evidence remains incomparable.';
  }catch(error){if(revision===policyRevision)policyStatus.textContent='Review rejected. Check the local recipes and evolution declaration, then review again.'}
});
policyDetailsButton.addEventListener('click',async()=>{
  if(!policyReviewed)return;const revision=policyRevision,request=policyReviewed;policyDetailsButton.disabled=true;policyStatus.textContent='Rechecking reviewed bytes before showing schema-sensitive details...';
  try{const response=await post('/api/policy-details',request);if(!response.ok)throw Error();const reviewed=await response.json();if(revision!==policyRevision)return;
    policyDetails.textContent=JSON.stringify(reviewed.details,null,2);policyDetails.hidden=false;policyHide.hidden=false;policyStatus.textContent='Schema-sensitive names and policy fragments are visible. This assessment is not approval.';
  }catch(error){if(revision===policyRevision){clearPolicyReview();policyStatus.textContent='Details rejected. Inputs may have changed; review the summary again.'}}
  finally{if(revision===policyRevision)policyDetailsButton.disabled=!policyReviewed}
});
"""

PLAN_PICKER_SCRIPT = r"""
chooseRecipe.addEventListener('click',async()=>{
  const revision=planRevision,previousRecipe=recipe.value;
  chooseRecipe.disabled=true;planOpenStatus.textContent='Choose a recipe file inside this workspace...';
  const current=()=>revision===planRevision&&recipe.value===previousRecipe&&token;
  try{
    const response=await post('/api/choose-recipe',{});if(!current())return;
    if(response.status===204){planOpenStatus.textContent='File selection cancelled.';return;}
    if(!response.ok){planOpenStatus.textContent='File could not be selected. Choose a file inside this workspace or enter its relative path.';return;}
    const selected=await response.json();if(!current())return;
    recipe.value=selected.recipe;planForm.requestSubmit();
  }catch(error){if(current())planOpenStatus.textContent='File picker unavailable. Enter a workspace-relative path instead.';}
  finally{if(token)chooseRecipe.disabled=false;}
});
"""

PLAN_CONTROLS_SCRIPT = r"""
let planRevision=0,controlBusy=false,controlsSource='';
const pendingEdits=new Map(),policyControls=document.getElementById('policy-controls'),controlsStatus=document.getElementById('controls-status'),effectivePolicy=document.getElementById('effective-policy'),inputLocations=document.getElementById('plan-inputs'),applyFields=document.getElementById('apply-fields');
function invalidatePlan(){planRevision++;downloadPlan.disabled=true;policySha.textContent='Revalidate to compute';effectivePolicy.textContent='Revalidate the current draft to review its effective policy.';}
function controlAvailability(disabled){policyControls.querySelectorAll('button,input,select').forEach(control=>control.disabled=disabled);}
function controlButton(text,action){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=text;button.addEventListener('click',action);return button;}
async function editControl(path=null,operation='set',value=null){
  if(controlBusy)return;
  const edits=Array.from(pendingEdits.values());if(path)edits.push({path,operation,value});if(!edits.length)return;
  const source=planSource.value;invalidatePlan();const revision=planRevision;
  controlBusy=true;controlAvailability(true);applyFields.disabled=true;validatePlan.disabled=true;
  controlsStatus.textContent='Applying field edits to the JSON draft...';
  try{
    const response=await post('/api/edit-plan',{source,edits});
    if(revision!==planRevision||source!==planSource.value)return;
    if(!response.ok)throw Error();
    const edited=await response.json();
    if(revision!==planRevision||source!==planSource.value)return;
    invalidatePlan();planSource.value=edited.source;renderPlanControls(edited.controls,path||[]);
    planStatus.textContent='Draft changed. Validate changes before downloading.';
    controlsStatus.textContent='Field edits applied. The draft remains unapproved.';
  }catch(error){if(revision===planRevision)controlsStatus.textContent='No field edits were applied. Check JSON-valued fields, or edit the source and refresh controls.';}
  finally{
    controlBusy=false;
    if(token){validatePlan.disabled=pendingEdits.size>0;applyFields.disabled=!pendingEdits.size||controlsSource!==planSource.value;if(controlsSource===planSource.value)controlAvailability(false);}
  }
}
function renderPlanControls(root,expandPath=[]){
  pendingEdits.clear();applyFields.disabled=true;validatePlan.disabled=controlBusy;
  controlsSource=planSource.value;
  const expanded=new Set(Array.from(policyControls.querySelectorAll('details[open]')).map(item=>item.dataset.path));
  for(let index=1;index<=expandPath.length;index++)expanded.add(JSON.stringify(expandPath.slice(0,index)));
  const initial=policyControls.childElementCount===0;
  policyControls.replaceChildren();
  function render(node){
    const field=document.createElement('div');field.className='policy-field';
    const name=node.path.length?String(node.path[node.path.length-1]):'Policy';
    const fullName=node.path.map(String).join(' / ');
    const heading=document.createElement('div');heading.className='control-heading';
    const title=document.createElement('span');title.textContent=name+(node.required?' (required)':'');heading.append(title);
    if(!node.present){
      field.classList.add('field-row');const note=document.createElement('span');note.className='control-note';note.textContent='Not set in source';
      const add=controlButton('Add '+name,()=>editControl(node.path,'set',node.initial));field.append(heading,note,add);return field;
    }
    if(node.children){
      const details=document.createElement('details');details.dataset.path=JSON.stringify(node.path);
      details.open=expanded.has(details.dataset.path)||(initial&&node.path.length===1&&name==='scope');
      const summary=document.createElement('summary');summary.textContent=name+(node.required?' (required)':'');details.append(summary);
      const contents=document.createElement('div');contents.className='control-children';
      if(node.description){const description=document.createElement('p');description.className='control-note';description.textContent=node.description;contents.append(description);}
      node.children.forEach(child=>contents.append(render(child)));
      if(node.kind==='array')contents.append(controlButton('Add item to '+name,()=>editControl([...node.path,node.children.length],'set',node.initial)));
      if(node.additional){
        const addRow=document.createElement('div');addRow.className='add-property';
        const key=document.createElement('input');key.type='text';key.setAttribute('aria-label','New property in '+fullName);key.placeholder='New property name';
        const add=controlButton('Add property',()=>{if(!key.value){key.focus();return}if(node.children.some(child=>child.path.at(-1)===key.value)){controlsStatus.textContent='That property already exists. Edit its current control.';return}editControl([...node.path,key.value],'set',node.additional_initial);});
        addRow.append(key,add);contents.append(addRow);
      }
      if(!node.required&&node.path.length)contents.append(controlButton('Remove '+name,()=>editControl(node.path,'remove',null)));
      details.append(contents);field.append(details);return field;
    }
    field.classList.add('field-row');
    const label=document.createElement('label');label.textContent=name+(node.required?' (required)':'');
    if(node.fixed){const fixed=document.createElement('code');fixed.textContent=node.value;field.append(label,fixed);if(!node.required)field.append(controlButton('Remove '+name,()=>editControl(node.path,'remove',null)));return field;}
    let input;
    const options=node.kind==='boolean'?['true','false']:node.choices;
    if(options.length){
      input=document.createElement('select');const blank=document.createElement('option');blank.value='';blank.textContent='Choose explicitly';blank.disabled=true;input.append(blank);
      options.forEach(value=>{const option=document.createElement('option');option.value=value;const decoded=JSON.parse(value);option.textContent=String(decoded);input.append(option);});input.value=options.includes(node.value)?node.value:'';
    }else{
      input=document.createElement('input');input.type='text';
      input.value=node.kind==='string'&&typeof JSON.parse(node.value)==='string'?JSON.parse(node.value):node.value;
      if(node.kind==='json')input.title='Enter a JSON string or number, keeping any quotes explicit.';
    }
    input.setAttribute('aria-label',fullName);input.dataset.path=JSON.stringify(node.path);
    input.addEventListener(options.length?'change':'input',()=>{
      pendingEdits.set(JSON.stringify(node.path),{path:node.path,operation:'set',value:options.length?input.value:node.kind==='string'?JSON.stringify(input.value):input.value});
      invalidatePlan();validatePlan.disabled=true;applyFields.disabled=false;planStatus.textContent='Field edits are pending. Apply field edits to update the JSON draft and conditional controls.';
    });
    label.append(input);field.append(label);
    if(node.kind==='json'){const hint=document.createElement('span');hint.className='control-note';hint.textContent='JSON string or number; keep quotes around strings.';field.append(hint);}
    if(node.description){const description=document.createElement('span');description.className='control-note';description.textContent=node.description;field.append(description);}
    if(!node.required)field.append(controlButton('Remove '+name,()=>editControl(node.path,'remove',null)));
    return field;
  }
  root.children.forEach(node=>policyControls.append(render(node)));
  controlAvailability(controlBusy);controlsStatus.textContent='Controls follow the released recipe schema. Unset fields stay omitted; review their effective values below.';
}
applyFields.addEventListener('click',()=>editControl());
document.getElementById('refresh-controls').addEventListener('click',async()=>{
  const source=planSource.value,revision=planRevision;controlsStatus.textContent='Reading controls from the JSON draft...';
  try{const response=await post('/api/plan-controls',{source});if(!response.ok)throw Error();const data=await response.json();if(revision!==planRevision||source!==planSource.value)return;renderPlanControls(data.controls);}
  catch(error){if(revision===planRevision)controlsStatus.textContent='Controls could not be read. Use a JSON object with recipe_version 1 through 6, then refresh.';}
});
document.getElementById('plan-input-form').addEventListener('submit',async event=>{
  event.preventDefault();const baseline=document.getElementById('plan-baseline').value,candidate=document.getElementById('plan-candidate').value,status=document.getElementById('plan-input-status'),revision=planRevision;
  status.textContent='Checking the explicit local input locations...';
  try{
    const response=await post('/api/plan-inputs',{baseline,candidate});
    if(revision!==planRevision||baseline!==document.getElementById('plan-baseline').value||candidate!==document.getElementById('plan-candidate').value)return;
    if(!response.ok)throw Error();
    document.getElementById('baseline').value=baseline;document.getElementById('candidate').value=candidate;
    status.textContent='Input locations copied to Run. Choose a saved recipe there; preflight and execution require a separate submission.';
  }catch(error){status.textContent='Input locations were rejected. Choose existing files or supported partitions inside this workspace and keep structured selectors explicit.';}
});
"""

SUITE_AUTHORING_SCRIPT = r"""
const authorForm=document.getElementById('suite-author-form'),authorStatus=document.getElementById('suite-author-status'),authorCases=document.getElementById('suite-author-cases'),authorReview=document.getElementById('suite-author-review'),authorExport=document.getElementById('suite-author-export');
let authoredCases=[],editingCase=null,authorRevision=0,authorReviewed=null,authorPending=false;
const authorField=id=>document.getElementById('author-'+id);
function invalidateAuthor(){authorRevision++;authorReviewed=null;authorReview.hidden=true;authorExport.disabled=true;authorStatus.textContent='Draft changed. Review the current cases and references before export.';}
function renderAuthoredCases(){
  authorCases.replaceChildren();
  authoredCases.forEach((item,index)=>{
    const row=document.createElement('div');row.className='authored-case';
    const label=document.createElement('span');label.textContent=(index+1)+'. '+item.id+' · '+item.recipe+' · '+item.baseline+' → '+item.candidate;row.append(label);
    const actions=document.createElement('div');actions.className='actions';
    for(const [name,action,disabled] of [
      ['Edit',()=>{editingCase=index;authorPending=true;invalidateAuthor();for(const field of ['id','recipe','baseline','candidate','description','expected_policy_sha256'])authorField(field).value=item[field]||'';authorField('tags').value=(item.tags||[]).join(', ');authorField('limits').value=JSON.stringify(item.limits||{});authorField('engine').value=item.execution?.engine||'';authorField('max_temp_bytes').value=item.execution?.max_temp_bytes||'';authorField('id').focus();},false],
      ['Up',()=>{[authoredCases[index-1],authoredCases[index]]=[authoredCases[index],authoredCases[index-1]];editingCase=null;invalidateAuthor();renderAuthoredCases();},index===0],
      ['Down',()=>{[authoredCases[index],authoredCases[index+1]]=[authoredCases[index+1],authoredCases[index]];editingCase=null;invalidateAuthor();renderAuthoredCases();},index===authoredCases.length-1],
      ['Remove',()=>{authoredCases.splice(index,1);editingCase=null;invalidateAuthor();renderAuthoredCases();},false]
    ]){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=name;button.disabled=disabled;button.addEventListener('click',action);actions.append(button)}
    row.append(actions);authorCases.append(row);
  });
}
document.getElementById('author-case-form').addEventListener('input',()=>{authorPending=true;invalidateAuthor()});
document.getElementById('author-case-form').addEventListener('change',()=>{authorPending=true;invalidateAuthor()});
document.getElementById('author-discard').addEventListener('click',()=>{editingCase=null;authorPending=false;document.getElementById('author-case-form').reset();authorField('limits').value='{}';invalidateAuthor()});
document.getElementById('author-case-form').addEventListener('submit',event=>{
  event.preventDefault();try{
    const item={id:authorField('id').value,recipe:authorField('recipe').value,baseline:authorField('baseline').value,candidate:authorField('candidate').value};
    const tags=authorField('tags').value.split(',').map(value=>value.trim()).filter(Boolean);if(tags.length)item.tags=tags;
    for(const field of ['description','expected_policy_sha256'])if(authorField(field).value)item[field]=authorField(field).value;
    const limits=JSON.parse(authorField('limits').value||'{}');if(Object.keys(limits).length)item.limits=limits;
    if(authorField('engine').value){item.execution={engine:authorField('engine').value};if(authorField('max_temp_bytes').value)item.execution.max_temp_bytes=Number(authorField('max_temp_bytes').value)}
    if(editingCase===null)authoredCases.push(item);else authoredCases[editingCase]=item;
    editingCase=null;authorPending=false;event.currentTarget.reset();authorField('limits').value='{}';invalidateAuthor();renderAuthoredCases();
  }catch(error){authorStatus.textContent='Case limits must be a JSON object. Review also checks released limits and policies.'}
});
authorForm.addEventListener('input',invalidateAuthor);
function authoredDraft(){const defaults=JSON.parse(authorField('defaults').value||'{}');const draft={suite_version:2,cases:authoredCases};if(Object.keys(defaults).length)draft.defaults={limits:defaults};return draft}
authorForm.addEventListener('submit',async event=>{
  event.preventDefault();if(authorPending){authorStatus.textContent='Apply or discard the current case edits before reviewing the suite.';return}const revision=++authorRevision;authorReviewed=null;authorReview.hidden=true;authorExport.disabled=true;authorStatus.textContent='Validating draft at the chosen destination and checking local references...';
  try{const request={destination:authorField('destination').value,draft:authoredDraft()};const response=await post('/api/suite-draft-review',request);if(!response.ok)throw Error();const reviewed=await response.json();if(revision!==authorRevision)return;authorReviewed={...request,review_id:reviewed.review_id};document.getElementById('suite-author-policy').textContent=reviewed.suite_policy_sha256;document.getElementById('suite-author-order').textContent=reviewed.case_ids.join(' → ');authorReview.hidden=false;authorExport.disabled=false;authorStatus.textContent='Unapproved draft reviewed. Check case order, references, limits and policy locks before export.'}
  catch(error){if(revision===authorRevision)authorStatus.textContent='Review rejected. Check case IDs, limits, execution settings, locks, destination and current local references.'}
});
authorExport.addEventListener('click',async()=>{if(!authorReviewed)return;const revision=authorRevision,request=authorReviewed;authorExport.disabled=true;authorStatus.textContent='Rechecking draft and installing one new local file...';try{const response=await post('/api/suite-draft-export',request);if(!response.ok)throw Error();const result=await response.json();if(revision!==authorRevision)return;authorReviewed=null;authorStatus.textContent='Unapproved suite draft exported to '+result.destination+'. Validate it in Suite plan review before running.'}catch(error){if(revision===authorRevision)authorStatus.textContent='Export rejected. References may have changed or the destination may exist. Review again.';authorReviewed=null}finally{authorExport.disabled=true}});
"""

